mapper.update:
UPDATE `character`
SET ch_level = #{chLevel},
    ch_exp = #{chExp}
WHERE user_num = #{userNum}

mapper.select:
SELECT COUNT(*) 
FROM exp_history eh
JOIN `character` c ON eh.ch_num = c.ch_num
WHERE c.user_num = #{userNum}
  AND eh.ed_num = #{edNum}
  AND DATE(eh.eh_created_at) = CURRENT_DATE()
